export const CATEGORY_NAMES = Object.keys(CATEGORY_DATA)

export const getAllCodingProblems = () => {
  return Object.values(CATEGORY_DATA).flat()
}

export const getProblemList = ({ difficulty = "Beginner", category = "All" } = {}) => {
  const normalizedCategory = category === "All" ? "" : category
  const allProblems = getAllCodingProblems()

  return allProblems.filter((problem) => {
    const categoryMatch =
      !normalizedCategory ||
      problem.category.toLowerCase() === normalizedCategory.toLowerCase()

    const difficultyMatch =
      !difficulty ||
      problem.difficulty.toLowerCase() === String(difficulty).toLowerCase()

    return categoryMatch && difficultyMatch
  })
}

export const prepareProblemForLanguage = (problem, language = "javascript") => {
  const safeLanguage = String(language || "javascript").toLowerCase()

  return {
    ...problem,
    starterCode:
      problem.languageStarters?.[safeLanguage] ||
      LANGUAGE_STARTERS[safeLanguage] ||
      LANGUAGE_STARTERS.javascript
  }
}

export default CATEGORY_DATA
